/** The `CostParameters` object of the `commercial` module. */
export interface CostParameters {
  /** Absent on a core term other than `CPA`. The rules that make an action billable: the evidence that confirms it, which content or context gets credit, and how cancellations, returns, fraud, and duplicate reports change the count. Where the document conflicts with a typed field of the binding record (§ 4.1.1), such as `action_type`, `attribution_window`, or `action_source`, the typed field governs */
  action_definition?: DocumentRef;
  /** Who reports the action */
  action_source?: Measurer;
  /** The kind of action counted. Core terms in IAB Tech Lab ECAPI 1.0: its `event_type` values, from the Standard Events and Additional Events tables both, other than `custom`, such as `purchase` or `install`. Any other action is an extension term, such as `shop.example:store_visit` */
  action_type?: CostParametersActionType;
  /** How long after exposure an action counts */
  attribution_window?: Duration;
  /** Absent unless `rate_unit` is `day`. The zone whose calendar days the rate buys: each calendar day in that zone that the flight touches is one unit. The flight's `end` is its last second, inclusive (§ 2.2), so a flight to the end of a day ends at 23:59:59 in that zone, and an `end` at the next midnight adds that day */
  calendar_zone?: IanaZone;
  /** The rated demographic, such as `ratings.example:adults_25_54`. Its definition states whether co-viewers and impressions of unknown age count, or says `unknown`. This version lists no core terms */
  demographic?: CostParametersDemographic;
  /** `hour` | `day` | `week`. The unit the rate buys, counted in elapsed units unless `calendar_zone` is present */
  rate_unit?: CostParametersRateUnit;
  /** Who supplies the ratings */
  rating_source?: Measurer;
  /** The fraction of the creative played that makes a view. Absent when `view_s` is present */
  view_fraction?: Fraction;
  /** Seconds played that make a view. Absent when `view_fraction` is present */
  view_s?: SafeInteger;
  /** The viewability standard that counts a unit. Core term: `mrc`, the MRC guidelines that `viewable_rate` cites (§ 5.7.1) */
  viewability_standard?: CostParametersViewabilityStandard;
}
